import sys
from collections import deque

def main():
    import sys
    input = sys.stdin.read().split()
    index = 0
    t = int(input[index])
    index += 1
    results = []
    for _ in range(t):
        n = int(input[index])
        m = int(input[index + 1])
        index += 2
        a = list(map(int, input[index:index + n - 1]))
        index += n - 1
        b = list(map(int, input[index:index + n - 1]))
        graph = [[] for _ in range(n)]
        index += n - 1
        for _ in range(m):
            u = int(input[index]) - 1
            v = int(input[index + 1]) - 1
            graph[u].append(v)
            graph[v].append(u)
            index += 2
        def bfs(start_power):
            visited = [False] * n
            queue = deque([(start_power, 0)])
            visited[0] = True
            while queue:
                power, cave = queue.popleft()
                for neighbor in graph[cave]:
                    if not visited[neighbor]:
                        if neighbor == 0:
                            visited[neighbor] = True
                            queue.append((power, neighbor))
                        else:
                            if power > a[neighbor - 1]:
                                new_power = power + b[neighbor - 1]
                                visited[neighbor] = True
                                queue.append((new_power, neighbor))
            return all(visited)
        low, high = 1, 10**18
        while low < high:
            mid = (low + high) // 2
            if bfs(mid):
                high = mid
            else:
                low = mid + 1
        results.append(low)
    for result in results:
        print(result)

if __name__ == "__main__":
    main()
